fn text(value:&serde_json::Value,key:&str)->String{value[key].as_str().unwrap().to_owned()}
fn source()->RunArtifact{
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let value=&fixture["snapshot"];
 let fingerprints=|rows:&serde_json::Value|rows.as_array().unwrap().iter().map(|row|crate::PortFingerprint{port_id:text(row,"portId"),fingerprint:text(row,"fingerprint")}).collect();
 RunArtifact{schema:text(value,"schema"),workflow_ref:text(value,"workflowRef"),workflow_checkpoint_id:text(value,"workflowCheckpointId"),input_collection_ref:text(value,"inputCollectionRef"),input_snapshot_id:text(value,"inputSnapshotId"),parameter_values:value["parameterValues"].as_array().unwrap().iter().map(|row|crate::RunParameterValue{parameter_id:text(row,"parameterId"),value:text(row,"value")}).collect(),output_collection_ref:text(value,"outputCollectionRef"),status:match value["status"].as_str().unwrap(){"pending"=>crate::RunStatus::Pending,"running"=>crate::RunStatus::Running,"succeeded"=>crate::RunStatus::Succeeded,"failed"=>crate::RunStatus::Failed,"canceled"=>crate::RunStatus::Canceled,_=>panic!("invalid neutral status")},trigger:{let row=&value["trigger"];match row["kind"].as_str().unwrap(){"manual"=>crate::RunTrigger::Manual{actor:text(row,"actor")},"automation"=>crate::RunTrigger::Automation{automation_ref:text(row,"automationRef"),event_fingerprint:text(row,"eventFingerprint")},_=>panic!("invalid neutral trigger")}},node_records:value["nodeRecords"].as_array().unwrap().iter().map(|row|crate::RunNodeRecord{node_id:text(row,"nodeId"),status:match row["status"].as_str().unwrap(){"computed"=>crate::RunNodeStatus::Computed,"cacheHit"=>crate::RunNodeStatus::CacheHit,"failed"=>crate::RunNodeStatus::Failed,_=>panic!("invalid neutral node status")},document_fingerprint:text(row,"documentFingerprint"),config_fingerprint:text(row,"configFingerprint"),input_fingerprints:fingerprints(&row["inputFingerprints"]),output_fingerprints:fingerprints(&row["outputFingerprints"]),outputs:row["outputs"].as_array().unwrap().iter().map(|row|crate::RunOutputArtifact{port_id:text(row,"portId"),artifact_id:text(row,"artifactId"),path:text(row,"path")}).collect(),duration_ms:row["durationMs"].as_f64().unwrap()}).collect(),logs:value["logs"].as_array().unwrap().iter().map(|row|crate::RunLogLine{node_id:text(row,"nodeId"),level:text(row,"level"),message:text(row,"message"),at:text(row,"at")}).collect(),started_at:text(value,"startedAt"),finished_at:value.get("finishedAt").filter(|value|!value.is_null()).map(|value|value.as_str().unwrap().to_owned()),sealed:value["sealed"].as_bool().unwrap()}
}
fn native(value:&RunArtifact,text:bool)->RunArtifact{if text{<RunArtifact as store::ArtifactDsl>::parse_dsl(&store::ArtifactDsl::print_dsl(value)).unwrap()}else{<RunArtifact as store::ArtifactPack>::decode_pack_with(&store::ArtifactPack::encode_pack_with(value,&store::PackEncodeOptions::default()).unwrap(),&store::PackDecodeOptions::default()).unwrap()}}
