use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteSnapshotProgress,SnapshotEncoding,export_sqlite_database,import_sqlite_database}};
fn laws()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn numeric_semantics(value:serde_json::Value)->serde_json::Value{match value{serde_json::Value::Number(value)=>serde_json::Value::Number(serde_json::Number::from_f64(value.as_f64().unwrap()).unwrap()),serde_json::Value::Array(values)=>serde_json::Value::Array(values.into_iter().map(numeric_semantics).collect()),serde_json::Value::Object(values)=>serde_json::Value::Object(values.into_iter().map(|(key,value)|(key,numeric_semantics(value))).collect()),value=>value}}
#[test]
fn sqlite_semantic_run_authored_neutral_json_schema_matches_the_native_public_value_bridge(){
 let fixture=laws();let expected=source();let actual:RunArtifact=semio_framework_pack_json::from_json_str(&fixture["snapshot"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();assert_eq!(actual,expected);
 let json:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&actual)).unwrap();assert!(json.get("workflow_ref").is_none());assert_eq!(numeric_semantics(json),numeric_semantics(fixture["snapshot"].clone()));
}
fn database(value:&RunArtifact)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(value:&SqliteDatabase)->RunArtifact{RunArtifact::from_sqlite_database(value,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn file(value:&RunArtifact)->Vec<u8>{export_sqlite_database(&database(value),SqliteDatabaseLimits::default(),&mut |_|true).unwrap()}
fn payload(value:&RunArtifact,encoding:SnapshotEncoding)->store::io_schema::IoPayload{match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(value)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(value))}}
fn dialect()->semio_framework_artifact_reference::ArtifactDialect{semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"os.run".into(),standard:"1".into(),subset:"*".into()}}
fn oracle(script:&str,input:&[u8])->Vec<u8>{use std::{io::Write,process::{Command,Stdio}};let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(input).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));output.stdout}
#[test]
fn sqlite_semantic_run_full_fields_are_independently_queryable_and_surrogate_edits_reconstruct(){
 let mut expected=source();let bytes=file(&expected);let script=r#"import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query("SELECT count(*) AS n FROM sqlite_schema WHERE type='table'").get().n!==7n)throw Error('table ownership');const nodes=db.query('SELECT node_id,status,duration_ms,duration_ms_bits FROM run_node ORDER BY ordinal').all();const word=Buffer.alloc(8);word.writeDoubleBE(1.25);if(nodes.length!==3||nodes[0].node_id!==''||nodes[0].duration_ms_bits!==word.readBigInt64BE()||nodes[2].status!==2n)throw Error('typed duration query');const p=db.query('SELECT parameter_id,value FROM run_parameter_value ORDER BY ordinal').all();if(p[0].parameter_id!==''||p[1].value!=='\0世界')throw Error('ordered literal parameter');db.run('UPDATE run_document SET workflow_ref=?',['edited\0😀']);db.run('UPDATE run_node SET id=id+90');db.run('UPDATE run_port_fingerprint SET node_id=node_id+90,id=id+90');db.run('UPDATE run_output_artifact SET node_id=node_id+90,id=id+90,path=?',['new\0世界']);db.run('UPDATE run_parameter_value SET id=id+90');db.run('UPDATE run_log SET id=id+90');db.run('UPDATE run_trigger SET id=id+90');await Bun.write(Bun.stdout,db.serialize());db.close();"#;
 let edited=oracle(script,&bytes);expected.workflow_ref="edited\0😀".into();for node in &mut expected.node_records{for output in &mut node.outputs{output.path="new\0世界".into()}}assert_eq!(restore(&import_sqlite_database(&edited,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()),expected);
}
#[test]
fn sqlite_semantic_run_raw_duration_words_reach_both_erased_native_outputs(){
 let codec=store::ArtifactCodec::bare::<RunArtifact,RunMutation>(S_RUN_SCHEMA);let owner=codec.snapshot_sqlite.unwrap();for hex in laws()["binary64Words"].as_array().unwrap(){let bits=u64::from_str_radix(hex.as_str().unwrap(),16).unwrap();let mut expected=source();for node in &mut expected.node_records{node.duration_ms=f64::from_bits(bits)}for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let d=with_original_decode(&native_caller_policy(),SqliteDatabaseLimits::default(),&mut |_|true,&mut |_|true,|_|{},|original_sql,original_owner|(owner.export)(&codec.schema,&dialect(),&payload(&expected,encoding),original_sql,original_owner)).unwrap().value;let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let d=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(restore(&d).node_records.iter().map(|n|n.duration_ms.to_bits()).collect::<Vec<_>>(),vec![bits;3]);let output={let mut original_input=Some(d);with_original_encode(&native_caller_policy(),SqliteDatabaseLimits::default(),&mut |_|true,&mut |_|true,|_|{},|original_sql,original_owner|(owner.import)(&codec.schema,&dialect(),&mut original_input,encoding,original_sql,original_owner))}.unwrap().value;let actual=with_original_decode(&native_caller_policy(),SqliteDatabaseLimits::default(),&mut |_|true,&mut |_|true,|_|{},|original_sql,original_owner|RunArtifact::decode_sqlite_snapshot_native(&output,original_sql,original_owner)).unwrap();assert_eq!(actual.node_records.iter().map(|n|n.duration_ms.to_bits()).collect::<Vec<_>>(),vec![bits;3]);assert_eq!(actual.trigger,expected.trigger);assert_eq!(actual.parameter_values,expected.parameter_values);}}
}
#[test]
fn sqlite_semantic_run_independent_malformed_edits_refuse_all_declared_relationships(){
 let bytes=file(&source());let script=r#"import{Database}from'bun:sqlite';const input=JSON.parse(await Bun.stdin.text());const results=[];for(const sql of input.sql){const db=Database.deserialize(new Uint8Array(input.bytes));db.run('PRAGMA ignore_check_constraints=ON');db.run(sql);results.push(Array.from(db.serialize()));db.close()}await Bun.write(Bun.stdout,JSON.stringify(results));"#;let fixture=laws();let edited:Vec<Vec<u8>>=serde_json::from_slice(&oracle(script,serde_json::json!({"bytes":bytes,"sql":fixture["malformedSql"]}).to_string().as_bytes())).unwrap();assert_eq!(edited.len(),18);for(sql,bytes)in fixture["malformedSql"].as_array().unwrap().iter().zip(edited){assert!(import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).and_then(|d|RunArtifact::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))).is_err(),"{sql}")}
}
#[test]
fn sqlite_semantic_run_semantic_limits_admit_exact_rows_and_refuse_tiny_owned_native_frontiers(){
 let expected=source();let d=database(&expected);let limits=SqliteDatabaseLimits::default();assert_eq!(d.tables.iter().map(|t|t.rows.len()).sum::<usize>(),13);assert!(expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:13,..limits})).is_ok());assert!(expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:12,..limits})).is_err());assert!(RunArtifact::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1,..limits})).is_err());for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{for limit in[SqliteDatabaseLimits{max_rows:12,..limits},SqliteDatabaseLimits{max_value_bytes:1,..limits},SqliteDatabaseLimits{max_file_bytes:1,..limits}]{assert!(with_original_decode(&native_caller_policy(),limit,&mut |_|true,&mut |_|true,|_|{},|original_sql,original_owner|RunArtifact::decode_sqlite_snapshot_native(&payload(&expected,encoding),original_sql,original_owner)).is_err());assert!(with_original_encode(&native_caller_policy(),limit,&mut |_|true,&mut |_|true,|_|{},|original_sql,original_owner|expected.encode_sqlite_snapshot_native(encoding,original_sql,original_owner)).is_err())}}
}
#[test]
fn sqlite_semantic_run_long_literal_unicode_cancellation_exposes_interior_owned_frontiers(){
 let mut expected=source();expected.logs[0].message="😀".repeat(laws()["control"]["largeCharacters"].as_u64().unwrap()as usize);let d=database(&expected);let limits=SqliteDatabaseLimits::default();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{let mut reached=false;let mut callback=|event:SqliteSnapshotProgress|if event.phase==phase&&event.total>=65536&&event.completed>=65536&&event.completed<event.total{reached=true;false}else{true};let mut control=SqliteSnapshotControl::new(&mut callback,limits);let rejected=match phase{SqliteSnapshotPhase::ProjectSnapshot=>expected.to_sqlite_database(&mut control).is_err(),SqliteSnapshotPhase::ReconstructSnapshot=>RunArtifact::from_sqlite_database(&d,&mut control).is_err(),SqliteSnapshotPhase::DecodeNative=>with_original_decode(&native_caller_policy(),limits,&mut callback,&mut |_|true,|_|{},|original_sql,original_owner|RunArtifact::decode_sqlite_snapshot_native(&payload(&expected,SnapshotEncoding::Text),original_sql,original_owner)).is_err(),SqliteSnapshotPhase::EncodeNative=>with_original_encode(&native_caller_policy(),limits,&mut callback,&mut |_|true,|_|{},|original_sql,original_owner|expected.encode_sqlite_snapshot_native(SnapshotEncoding::Text,original_sql,original_owner)).is_err(),_=>panic!("unexpected phase")};assert!(rejected,"{phase:?}");assert!(reached,"{phase:?}")}
}
