mod owned_requests;

fn run_cell_equal(actual:&RunArtifact,expected:&RunArtifact){assert_eq!(actual.node_records.len(),expected.node_records.len());for(actual,expected)in actual.node_records.iter().zip(&expected.node_records){assert_eq!(actual.duration_ms.to_bits(),expected.duration_ms.to_bits());}let mut actual=actual.clone();let mut expected=expected.clone();for node in&mut actual.node_records{node.duration_ms=0.0;}for node in&mut expected.node_records{node.duration_ms=0.0;}assert_eq!(actual,expected);}
#[test]
fn sqlite_semantic_run_complete_sql_cells_are_exact_for_both_triggers_and_all_ieee_branches(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/📏️semantic-cells/🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){let name=case["name"].as_str().unwrap();let mut expected=source();if name.len()==16&&name.bytes().all(|byte|byte.is_ascii_hexdigit()){let bits=u64::from_str_radix(name,16).unwrap();for node in&mut expected.node_records{node.duration_ms=f64::from_bits(bits)}}else if name!="base"{let(kind,finished)=name.split_once('-').unwrap();let fixture=laws();let trigger=fixture["triggers"].as_array().unwrap().iter().find(|trigger|trigger["kind"]==kind).unwrap();expected.trigger=match kind{"manual"=>crate::RunTrigger::Manual{actor:trigger["actor"].as_str().unwrap().into()},"automation"=>crate::RunTrigger::Automation{automation_ref:trigger["automationRef"].as_str().unwrap().into(),event_fingerprint:trigger["eventFingerprint"].as_str().unwrap().into()},_=>panic!("closed trigger")};expected.finished_at=match finished{"absent"=>None,"empty"=>Some(String::new()),"unicode"=>Some("\0\u{1f600}".into()),_=>panic!("closed finished presence")};}
  let bytes=usize::try_from(case["bytes"].as_u64().unwrap()).unwrap();let defaults=SqliteDatabaseLimits::default();let d=database(&expected);assert_eq!(d.tables.len(),usize::try_from(law["tables"].as_u64().unwrap()).unwrap());assert_eq!(d.tables.iter().map(|table|table.rows.len()).sum::<usize>(),usize::try_from(law["rows"].as_u64().unwrap()).unwrap());
  for allowance in[bytes,bytes-1]{let limits=SqliteDatabaseLimits{max_value_bytes:allowance,..defaults};let projected=expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(projected.is_ok(),allowance==bytes,"project {name}");let restored=RunArtifact::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(restored.is_ok(),allowance==bytes,"reconstruct {name}");if allowance==bytes{run_cell_equal(&restored.unwrap(),&expected);}for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let encoded=with_original_encode(&native_caller_policy(),limits,&mut |_|true,&mut |_|true,|_|{},|original_sql,original_owner|expected.encode_sqlite_snapshot_native(encoding,original_sql,original_owner));assert_eq!(encoded.is_ok(),allowance==bytes,"encode {name} {encoding:?}");let decoded=with_original_decode(&native_caller_policy(),limits,&mut |_|true,&mut |_|true,|_|{},|original_sql,original_owner|RunArtifact::decode_sqlite_snapshot_native(&payload(&expected,encoding),original_sql,original_owner));assert_eq!(decoded.is_ok(),allowance==bytes,"decode {name} {encoding:?}");if allowance==bytes{run_cell_equal(&decoded.unwrap(),&expected);}}}
  println!("[DEBUG] Run complete native SQL cells case={name} bytes={bytes}");
 }
}

#[semio_framework_async_macros::async_test]
async fn sqlite_semantic_run_normal_owner_registration_public_words_and_independent_edit(){
 use store::{ArtifactPack,ArtifactDsl};use semio_framework_value::{DslValue,Number,ToValue};
 struct Owned(Option<RunArtifact>);impl Owned{fn new(value:RunArtifact)->Self{Self(Some(value))}fn get(&self)->&RunArtifact{self.0.as_ref().unwrap()}}impl Drop for Owned{fn drop(&mut self){if let Some(value)=self.0.take(){value.retire_sqlite_snapshot();}}}
 fn exact(a:&DslValue,b:&DslValue){match(a,b){(DslValue::Number(Number::Float(a)),DslValue::Number(Number::Float(b)))=>assert_eq!(a.to_bits(),b.to_bits()),(DslValue::Array(a),DslValue::Array(b))=>{assert_eq!(a.len(),b.len());for(a,b)in a.iter().zip(b){exact(a,b);}},(DslValue::Object(a),DslValue::Object(b))=>{assert_eq!(a.len(),b.len());for((ka,a),(kb,b))in a.iter().zip(b){assert_eq!(ka,kb);exact(a,b);}},_=>assert_eq!(a,b)}}
 let registration=<RunArtifact as ArtifactPack>::native_snapshot_registration();assert!(registration.is_some(),"RunArtifact must publish normal owning native registration rather than a test-local bare codec");let(owner,codec)=registration.unwrap();assert_eq!(owner.artifact_kind,"os.run");assert_eq!(owner.standard.0,"1");assert_eq!(owner.subset.0,"*");assert!(codec.snapshot_sqlite.is_some());store::io::register_native_document_codec(owner,codec).unwrap();
 let sqlite=semio_framework_artifact_reference::ArtifactDialect::from(store::io_schema::SQLITE_SNAPSHOT);for route in[store::io::io_mechanism::io_route(&dialect(),&sqlite,1).await.unwrap().value,store::io::io_mechanism::io_route(&sqlite,&dialect(),1).await.unwrap().value]{assert_eq!(route.hops.len(),1);assert_eq!(route.fidelity,store::io_schema::IoFidelity::Exact);}
 for hex in laws()["binary64Words"].as_array().unwrap(){let bits=u64::from_str_radix(hex.as_str().unwrap(),16).unwrap();let mut literal=source();for node in &mut literal.node_records{node.duration_ms=f64::from_bits(bits);}let expected=Owned::new(literal);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let bytes=store::io::io_mechanism::io_export_sqlite_snapshot(&dialect(),expected.get(),encoding,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;let actual=Owned::new(store::io::io_mechanism::io_import_sqlite_snapshot::<RunArtifact>(&dialect(),&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value);exact(&actual.get().to_value(),&expected.get().to_value());assert_eq!(actual.get().encode_pack(),expected.get().encode_pack());assert_eq!(actual.get().print_dsl(),expected.get().print_dsl());
 let script=r#"import{Database}from'bun:sqlite';const d=Database.deserialize(await Bun.stdin.bytes(),{safeIntegers:true});if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query("SELECT COUNT(*) AS n FROM sqlite_schema WHERE type='table'").get().n!==8n)throw Error('all7RunPlusMetadata');if(d.query('SELECT COUNT(*) AS n FROM run_node').get().n!==3n||d.query('SELECT COUNT(*) AS n FROM run_parameter_value').get().n!==2n)throw Error('populatedRows');if(d.query('SELECT value FROM run_parameter_value ORDER BY ordinal DESC LIMIT 1').get().value!=='\u0000世界')throw Error('literal');if(d.query('SELECT artifact_kind,standard,subset FROM semio_snapshot').get().artifact_kind!=='os.run')throw Error('metadata');d.query('UPDATE run_document SET workflow_ref=? WHERE id=1').run('independent 日本\u0000');await Bun.write(Bun.stdout,d.serialize());d.close();"#;
 let edited=oracle(script,&bytes);let actual=Owned::new(store::io::io_mechanism::io_import_sqlite_snapshot::<RunArtifact>(&dialect(),&edited,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value);let mut literal=source();for node in &mut literal.node_records{node.duration_ms=f64::from_bits(bits);}literal.workflow_ref="independent 日本\0".into();let literal=Owned::new(literal);exact(&actual.get().to_value(),&literal.get().to_value());assert_eq!(actual.get().encode_pack(),literal.get().encode_pack());assert_eq!(actual.get().print_dsl(),literal.get().print_dsl());
 }}
 eprintln!("[DEBUG] Run normal native registration reaches exact public words and independent edited owner");
}
